18	package org.keycloak.common.util;
19	
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.Collections;
23	import java.util.HashMap;
24	import java.util.HashSet;
25	import java.util.List;
26	import java.util.Map;
27	import java.util.Set;
28	import java.util.stream.Collectors;
29	
30	/**
31	 * @author <a href="mailto:jeroen.rosenberg@gmail.com">Jeroen Rosenberg</a>
32	 */
33	public class CollectionUtil {
34	
35	    public static String join(Collection<String> strings) {
36	        return join(strings, ", ");
37	    }
38	
39	    public static String join(Collection<String> strings, String separator) {
40	        return strings.stream().collect(Collectors.joining(String.valueOf(separator)));
41	    }
42	
43	    // Return true if all items from col1 are in col2 and viceversa. Order is not taken into account
44	    public static <T> boolean collectionEquals(Collection<T> col1, Collection<T> col2) {
45	        if (col1.size()!=col2.size()) {
46	            return false;
47	        }
48	        Map<T, Integer> countMap = new HashMap<>();
49	        for(T o : col1) {
50	            countMap.merge(o, 1, (v1, v2) -> v1 + v2);
51	        }
52	        for(T o : col2) {
53	            Integer v = countMap.get(o);
54	            if (v==null) {
55	                return false;
56	            }
57	            if (v == 1) {
58	                countMap.remove(o);
59	            } else {
60	                countMap.put(o, v-1);
61	            }
62	        }
63	        return countMap.isEmpty();
64	    }
65	
66	    public static boolean isEmpty(Collection<?> collection) {
67	        return collection == null || collection.isEmpty();
68	    }
69	
70	    public static boolean isNotEmpty(Collection<?> collection) {
71	        return !isEmpty(collection);
72	    }
73	
74	    public static <T> Set<T> collectionToSet(Collection<T> collection) {
75	        return collection == null ? null : new HashSet<>(collection);
76	    }
77	
78	    /**
79	     * Splits the given collection into consecutive chunks of at most {@code chunkSize} elements,
80	     * preserving iteration order. Every chunk except possibly the last has exactly {@code chunkSize}
81	     * elements. The returned chunks are independent copies and do not reference the source collection.
82	     *
83	     * @param items the collection to split; may be {@code null}
84	     * @param chunkSize the maximum number of elements per chunk; must be greater than 0
85	     * @return list of chunks; an empty list if {@code items} is {@code null} or empty
86	     * @throws IllegalArgumentException if {@code chunkSize} is not positive
87	     */
88	    public static <T> List<List<T>> partition(Collection<T> items, int chunkSize) {
89	        if (chunkSize <= 0) {
90	            throw new IllegalArgumentException("chunkSize must be greater than 0");
91	        }
92	        if (isEmpty(items)) {
93	            return Collections.emptyList();
94	        }
95	        int chunkCapacity = Math.min(chunkSize, items.size());
96	        // ceil(size / chunkSize) without overflowing for large chunkSize values; items is non-empty here
97	        int chunkCount = 1 + (items.size() - 1) / chunkSize;
98	        List<List<T>> chunks = new ArrayList<>(chunkCount);
99	        List<T> chunk = new ArrayList<>(chunkCapacity);
100	        for (T item : items) {
101	            chunk.add(item);
102	            if (chunk.size() == chunkSize) {
103	                chunks.add(chunk);
104	                chunk = new ArrayList<>(chunkCapacity);
105	            }
106	        }
107	        if (!chunk.isEmpty()) {
108	            chunks.add(chunk);
109	        }
110	        return chunks;
111	    }
112	}
