17	package org.keycloak.common.util;
18	
19	import java.io.ByteArrayInputStream;
20	import java.io.ByteArrayOutputStream;
21	import java.io.File;
22	import java.io.IOException;
23	import java.io.InputStream;
24	import java.nio.charset.StandardCharsets;
25	import java.util.Optional;
26	
27	import org.jboss.logging.Logger;
28	import org.jboss.logging.Logger.Level;
29	
30	/**
31	 * A utility class for replacing properties in strings.
32	 *
33	 * @author <a href="mailto:jason@planet57.com">Jason Dillon</a>
34	 * @author <a href="Scott.Stark@jboss.org">Scott Stark</a>
35	 * @author <a href="claudio.vesco@previnet.it">Claudio Vesco</a>
36	 * @author <a href="mailto:adrian@jboss.com">Adrian Brock</a>
37	 * @author <a href="mailto:dimitris@jboss.org">Dimitris Andreadis</a>
38	 * @version <tt>$Revision: 2898 $</tt>
39	 */
40	public final class StringPropertyReplacer
41	{
42	
43	    private static final Logger logger = Logger.getLogger(StringPropertyReplacer.class);
44	
45	    /** File separator value */
46	    private static final String FILE_SEPARATOR = File.separator;
47	
48	    /** Path separator value */
49	    private static final String PATH_SEPARATOR = File.pathSeparator;
50	
51	    /** File separator alias */
52	    private static final String FILE_SEPARATOR_ALIAS = "/";
53	
54	    /** Path separator alias */
55	    private static final String PATH_SEPARATOR_ALIAS = ":";
56	
57	    private static final PropertyResolver NULL_RESOLVER = property -> null;
58	    private static PropertyResolver DEFAULT_PROPERTY_RESOLVER;
59	
60	    private static final int MAX_KEY_LENGTH = 1<<22;
61	
62	    public static void setDefaultPropertyResolver(PropertyResolver systemVariables) {
63	        DEFAULT_PROPERTY_RESOLVER = systemVariables;
64	    }
65	
66	    /**
67	     * Go through the input string and replace any occurrence of ${p} with
68	     * the System.getProperty(p) value. If there is no such property p defined,
69	     * then the ${p} reference will remain unchanged.
70	     *
71	     * If the property reference is of the form ${p:v} and there is no such property p,
72	     * then the default value v will be returned.
73	     *
74	     * If the property reference is of the form ${p1,p2} or ${p1,p2:v} then
75	     * the primary and the secondary properties will be tried in turn, before
76	     * returning either the unchanged input, or the default value.
77	     *
78	     * The property ${/} is replaced with System.getProperty("file.separator")
79	     * value and the property ${:} is replaced with System.getProperty("path.separator").
80	     *
81	     * @param string - the string with possible ${} references
82	     * @return the input string with all property references replaced if any.
83	     *    If there are no valid references the input string will be returned.
84	     */
85	    public static String replaceProperties(final String string) {
86	        return replaceProperties(string, getDefaultPropertyResolver());
87	    }
88	
89	    /**
90	     * Go through the input string and replace any occurrence of ${p} with
91	     * the value resolves from {@code resolver}. If there is no such property p defined,
92	     * then the ${p} reference will remain unchanged.
93	     *
94	     * If the property reference is of the form ${p:v} and there is no such property p,
95	     * then the default value v will be returned.
96	     *
97	     * If the property reference is of the form ${p1,p2} or ${p1,p2:v} then
98	     * the primary and the secondary properties will be tried in turn, before
99	     * returning either the unchanged input, or the default value.
100	     *
101	     * The property ${/} is replaced with System.getProperty("file.separator")
102	     * value and the property ${:} is replaced with System.getProperty("path.separator").
103	     *
104	     * @param string - the string with possible ${} references
105	     * @param resolver - the property resolver
106	     * @return the input string with all property references replaced if any.
107	     *    If there are no valid references the input string will be returned.
108	     */
109	    public static String replaceProperties(final String string, PropertyResolver resolver) {
110	        if (string == null) {
111	            return null;
112	        }
113	        int index = string.indexOf("${");
114	        if (index == -1) {
115	            return string;
116	        }
117	        try {
118	            return string.substring(0, index).concat(StreamUtil
119	                    .readString(replaceProperties(new ByteArrayInputStream(string.substring(index).getBytes(StandardCharsets.UTF_8)),
120	                            resolver), StandardCharsets.UTF_8));
121	        } catch (IOException e) {
122	            throw new RuntimeException(e); // not expected
123	        }
124	    }
125	
126	    public static InputStream replaceProperties(final InputStream source, PropertyResolver resolver) {
127	        return replaceProperties(source, false, resolver);
128	    }
129	
130	    private static InputStream replaceProperties(final InputStream source, boolean readUntilCurlyBrace, PropertyResolver resolver) {
131	        return new InputStream() {
132	            private ByteArrayInputStream buffer;
133	            private boolean closed;
134	            private int curlyBraceDepth;
135	
136	            @Override
137	            public int read() throws IOException {
138	                if (closed) {
139	                    throw new IOException("Stream closed");
140	                }
141	                // read off of the buffer first if possible
142	                if (buffer != null) {
143	                    int c = buffer.read();
144	                    if (c != -1) {
145	                        return c;
146	                    }
147	                    buffer = null;
148	                }
149	                // if no buffer, scan for } or ${
150	                int c = source.read();
151	                if (readUntilCurlyBrace) {
152	                    if (c == '}') {
153	                        if (curlyBraceDepth-- == 0) {
154	                            return -2;
155	                        }
156	                    } else if (c == '{') {
157	                        curlyBraceDepth++;
158	                    }
159	                }
160	                if (c != '$') {
161	                    return c;
162	                }
163	                int next = source.read();
164	                if (next != '{') {
165	                    buffer = new ByteArrayInputStream(new byte[] {(byte)c, (byte)next});
166	                    return read();
167	                }
168	                // determine the key
169	                int keyChar = -1;
170	                InputStream keyStream = replaceProperties(source, true, resolver);
171	                ByteArrayOutputStream bytes = new ByteArrayOutputStream();
172	                while ((keyChar = keyStream.read()) > -1) {
173	                    bytes.write((byte)keyChar);
174	                    if (bytes.size() == MAX_KEY_LENGTH) {
175	                        logger.log(Level.WARN, "Detected an unclosed ${, replacement will not be performed");
176	                        keyChar = -1;
177	                        break;
178	                    }
179	                }
180	                String keyString = bytes.toString(StandardCharsets.UTF_8.name());
181	                String replacement = null;
182	                if (keyChar == -1) {
183	                    // eof before } - prepend ${ and output directly
184	                    replacement = "${" + keyString;
185	                } else {
186	                    replacement = replaceProperty(resolver, keyString);
187	                    if (replacement == null) {
188	                        replacement = "${" + keyString + "}";
189	                    } else {
190	                        try {
191	                            replacement = replaceProperties(replacement, resolver);
192	                        } catch (StackOverflowError ex) {
193	                            throw new IllegalStateException("Infinite recursion happening when replacing properties on '" + replacement + "'");
194	                        }
195	                    }
196	                }
197	                buffer = new ByteArrayInputStream(replacement.getBytes(StandardCharsets.UTF_8));
198	                return read();
199	            }
200	
201	            @Override
202	            public void close() throws IOException {
203	                closed = true;
204	                source.close();
205	            }
206	        };
207	    }
208	
209	    private static String replaceProperty(PropertyResolver resolver, String key) {
210	        String value = null;
211	
212	        // check for alias
213	        if (FILE_SEPARATOR_ALIAS.equals(key))
214	        {
215	            value = FILE_SEPARATOR;
216	        }
217	        else if (PATH_SEPARATOR_ALIAS.equals(key))
218	        {
219	            value = PATH_SEPARATOR;
220	        }
221	        else
222	        {
223	            // check from the properties
224	            value = resolveValue(resolver, key);
225	
226	            if (value == null)
227	            {
228	                // Check for a default value ${key:default}
229	                int colon = key.indexOf(':');
230	                if (colon > 0)
231	                {
232	                    String realKey = key.substring(0, colon);
233	                    value = resolveValue(resolver, realKey);
234	
235	                    if (value == null)
236	                    {
237	                        // Check for a composite key, "key1,key2"
238	                        value = resolveCompositeKey(realKey, resolver);
239	
240	                        // Not a composite key either, use the specified default
241	                        if (value == null) {
242	                            value = key.substring(colon+1);
243	                        }
244	                    }
245	                }
246	                else
247	                {
248	                    // No default, check for a composite key, "key1,key2"
249	                    value = resolveCompositeKey(key, resolver);
250	                }
251	            }
252	        }
253	
254	        return value;
255	    }
256	
257	    private static String resolveCompositeKey(String key, PropertyResolver resolver)
258	    {
259	        String value = null;
260	
261	        // Look for the comma
262	        int comma = key.indexOf(',');
263	        if (comma > -1)
264	        {
265	            // If we have a first part, try resolve it
266	            if (comma > 0)
267	            {
268	                // Check the first part
269	                String key1 = key.substring(0, comma);
270	                value = resolveValue(resolver, key1);
271	            }
272	            // Check the second part, if there is one and first lookup failed
273	            if (value == null && comma < key.length() - 1)
274	            {
275	                String key2 = key.substring(comma + 1);
276	                value = resolveValue(resolver, key2);
277	            }
278	        }
279	        // Return whatever we've found or null
280	        return value;
281	    }
282	
283	    public interface PropertyResolver {
284	        String resolve(String property);
285	    }
286	
287	    private static String resolveValue(PropertyResolver resolver, String key) {
288	        if (resolver == null) {
289	            return getDefaultPropertyResolver().resolve(key);
290	        }
291	
292	        return resolver.resolve(key);
293	    }
294	
295	    private static PropertyResolver getDefaultPropertyResolver() {
296	        return Optional.ofNullable(DEFAULT_PROPERTY_RESOLVER).orElse(NULL_RESOLVER);
297	    }
298	}
299

