26	public class Retry {
27	
28	
29	    /**
30	     * Runs the given {@code runnable} at most {@code attemptsCount} times until it passes,
31	     * leaving {@code intervalMillis} milliseconds between the invocations.
32	     * The runnable is reexecuted if it throws a {@link RuntimeException} or {@link AssertionError}.
33	     * @param runnable
34	     * @param attemptsCount Total number of attempts to execute the {@code runnable}
35	     * @param intervalMillis
36	     * @return Index of the first successful invocation, starting from 0.
37	     */
38	    public static int execute(Runnable runnable, int attemptsCount, long intervalMillis) {
39	        int iteration = 0;
40	        while (true) {
41	            try {
42	                runnable.run();
43	                return iteration;
44	            } catch (RuntimeException | AssertionError e) {
45	                attemptsCount--;
46	                iteration++;
47	                if (attemptsCount > 0) {
48	                    try {
49	                        if (intervalMillis > 0) {
50	                            Thread.sleep(intervalMillis);
51	                        }
52	                    } catch (InterruptedException ie) {
53	                        Thread.currentThread().interrupt();
54	                        ie.addSuppressed(e);
55	                        throw new RuntimeException(ie);
56	                    }
57	                } else {
58	                    throw e;
59	                }
60	            }
61	        }
62	    }
63	
64	
65	    /**
66	     * Runs the given {@code runnable} at most {@code attemptsCount} times until it passes,
67	     * leaving some increasing random delay milliseconds between the invocations. It uses Exponential backoff + jitter algorithm
68	     * to compute the delay. More details https://aws.amazon.com/blogs/architecture/exponential-backoff-and-jitter/
69	     *
70	     * The base for delay is specified by {@code intervalBaseMillis} number.
71	     *
72	     * The runnable is reexecuted if it throws a {@link RuntimeException} or {@link AssertionError}.
73	     *
74	     * @param runnable
75	     * @param attemptsCount Total number of attempts to execute the {@code runnable}
76	     * @param intervalBaseMillis base for the exponential backoff + jitter
77	     *
78	     * @return Index of the first successful invocation, starting from 0.
79	     */
80	    public static int executeWithBackoff(AdvancedRunnable runnable, int attemptsCount, int intervalBaseMillis) {
81	        return executeWithBackoff(runnable, null, attemptsCount, intervalBaseMillis);
82	    }
83	
84	    public static int executeWithBackoff(AdvancedRunnable runnable, ThrowableCallback throwableCallback, int attemptsCount, int intervalBaseMillis) {
85	        int iteration = 0;
86	        while (true) {
87	            try {
88	                runnable.run(iteration);
89	                return iteration;
90	            } catch (RuntimeException | AssertionError e) {
91	
92	                if (throwableCallback != null) {
93	                    throwableCallback.handleThrowable(iteration, e);
94	                }
95	
96	                iteration++;
97	                if (iteration >= attemptsCount) {
98	                    throw e;
99	                }
100	                if (intervalBaseMillis <= 0) {
101	                    continue;
102	                }
103	                try {
104	                    long delay = computeBackoffInterval(intervalBaseMillis, iteration);
105	                    Thread.sleep(delay);
106	                } catch (InterruptedException ie) {
107	                    Thread.currentThread().interrupt();
108	                    e.addSuppressed(ie);
109	                    throw e;
110	                }
111	            }
112	        }
113	    }
114	
115	    public static int executeWithBackoff(AdvancedRunnable runnable, Duration timeout, int intervalBaseMillis) {
116	        return executeWithBackoff(runnable, null, timeout, intervalBaseMillis);
117	    }
118	
119	    public static int executeWithBackoff(AdvancedRunnable runnable, ThrowableCallback throwableCallback, Duration timeout, int intervalBaseMillis) {
120	        long maximumTime = Time.currentTimeMillis() + timeout.toMillis();
121	
122	        int iteration = 0;
123	        while (true) {
124	            try {
125	                runnable.run(iteration);
126	                return iteration;
127	            } catch (RuntimeException | AssertionError e) {
128	
129	                if (throwableCallback != null) {
130	                    throwableCallback.handleThrowable(iteration, e);
131	                }
132	
133	                iteration++;
134	                long remainingTime = maximumTime - Time.currentTimeMillis();
135	                if (remainingTime <= 0) {
136	                    throw e;
137	                }
138	
139	                if (intervalBaseMillis <= 0) {
140	                    continue;
141	                }
142	                try {
143	                    long delay = Math.min(remainingTime, computeBackoffInterval(intervalBaseMillis, iteration));
144	                    Thread.sleep(delay);
145	                } catch (InterruptedException ie) {
146	                    Thread.currentThread().interrupt();
147	                    e.addSuppressed(ie);
148	                    throw e;
149	                }
150	            }
151	        }
152	    }
153	
154	    public static int computeBackoffInterval(int base, int iteration) {
155	        return ThreadLocalRandom.current().nextInt(computeIterationBase(base, iteration));
156	    }
157	
158	    private static int computeIterationBase(int base, int iteration) {
159	        return base * (1 << iteration);
160	    }
161	
162	    /**
163	     * Runs the given {@code runnable} at most {@code attemptsCount} times until it passes,
164	     * leaving {@code intervalMillis} milliseconds between the invocations.
165	     * The runnable is reexecuted if it throws a {@link RuntimeException} or {@link AssertionError}.
166	     * @param supplier
167	     * @param attemptsCount Total number of attempts to execute the {@code runnable}
168	     * @param intervalMillis
169	     * @return Value generated by the {@code supplier}.
170	     */
171	    public static <T> T call(Supplier<T> supplier, int attemptsCount, long intervalMillis) {
172	        int iteration = 0;
173	        while (true) {
174	            try {
175	                return supplier.get(iteration);
176	            } catch (Exception | AssertionError e) {
177	                attemptsCount--;
178	                iteration++;
179	                if (attemptsCount > 0) {
180	                    try {
181	                        if (intervalMillis > 0) {
182	                            Thread.sleep(intervalMillis);
183	                        }
184	                    } catch (InterruptedException ie) {
185	                        Thread.currentThread().interrupt();
186	                        ie.addSuppressed(e);
187	                        throw new RuntimeException(ie);
188	                    }
189	                } else {
190	                    throw e;
191	                }
192	            }
193	        }
194	    }
