void executeShouldReturnZeroWhenFirstAttemptSucceeds() {
    AtomicInteger attempts = new AtomicInteger(0);
    int firstSuccess = Retry.execute(attempts::incrementAndGet, 3, 0);
    Assertions.assertEquals(0, firstSuccess);
    Assertions.assertEquals(1, attempts.get());
}

